const static_data = $getWorkflowStaticData('global');
const bot_token = $env.TELEGRAM_BOT_TOKEN;
const allowed_chat_id = String($env.TELEGRAM_CHAT_ID ?? '');
const tracking_parameters = ['gclid', 'gbraid', 'wbraid', 'gad_source', 'gad_campaignid', 'fbclid', 'msclkid', 'mc_cid', 'mc_eid', '_hsenc', '_hsmi'];

function cleanUrl(raw_url) {
	const without_hash = raw_url.split('#')[0];
	const question_mark = without_hash.indexOf('?');

	if (question_mark == -1) {
		return without_hash;
	}

	const base = without_hash.slice(0, question_mark);
	const kept_parameters = without_hash
		.slice(question_mark + 1)
		.split('&')
		.filter(function (parameter) {
			const key = parameter.split('=')[0];

			return key != '' && !key.startsWith('utm_') && !tracking_parameters.includes(key);
		});

	if (kept_parameters.length == 0) {
		return base;
	}

	return base + '?' + kept_parameters.join('&');
}

const response = await this.helpers.httpRequest({
	method: 'GET',
	url: 'https://api.telegram.org/bot' + bot_token + '/getUpdates',
	qs: {
		offset: static_data.offset ?? 0,
		timeout: 0,
		allowed_updates: JSON.stringify(['message']),
	},
	json: true,
});

const items = [];

for (const update of response.result) {
	static_data.offset = update.update_id + 1;

	const message = update.message;

	if (message == null || String(message.chat.id) != allowed_chat_id) {
		continue;
	}

	const found_url = (message.text ?? '').match(/https?:\/\/\S+/);

	if (found_url == null) {
		continue;
	}

	items.push({
		json: {
			chat_id: message.chat.id,
			message_id: message.message_id,
			url: cleanUrl(found_url[0]),
		},
	});
}

return items;

function findJobPosting(node) {
	if (node == null || typeof node != 'object') {
		return null;
	}

	if (Array.isArray(node)) {
		for (const entry of node) {
			const found = findJobPosting(entry);

			if (found != null) {
				return found;
			}
		}

		return null;
	}

	const type = node['@type'];

	if (type == 'JobPosting' || (Array.isArray(type) && type.includes('JobPosting'))) {
		return node;
	}

	if (node['@graph'] != null) {
		return findJobPosting(node['@graph']);
	}

	return null;
}

function toYearly(amount, unit) {
	if (amount == null || isNaN(Number(amount))) {
		return null;
	}

	const value = Number(amount);

	if (unit == 'MONTH') {
		return Math.round(value * 12);
	}

	if (unit == 'HOUR') {
		return Math.round(value * 40 * 52);
	}

	return Math.round(value);
}

function readJobPosting(html) {
	const pattern = /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
	let match;

	while ((match = pattern.exec(html)) != null) {
		let parsed;

		try {
			parsed = JSON.parse(match[1].trim());
		} catch (error) {
			continue;
		}

		const job = findJobPosting(parsed);

		if (job == null) {
			continue;
		}

		const organization = Array.isArray(job.hiringOrganization) ? job.hiringOrganization[0] : job.hiringOrganization;
		const job_location = Array.isArray(job.jobLocation) ? job.jobLocation[0] : job.jobLocation;
		const address = job_location?.address ?? {};
		const salary = job.baseSalary?.value ?? {};
		const unit = job.baseSalary?.value?.unitText ?? job.baseSalary?.unitText;
		const location_type = Array.isArray(job.jobLocationType) ? job.jobLocationType.join(',') : (job.jobLocationType ?? '');

		return {
			company: organization?.name ?? null,
			position: job.title ?? null,
			location: address.addressLocality ?? null,
			remote: location_type.includes('TELECOMMUTE'),
			salary_min: toYearly(salary.minValue ?? salary.value, unit),
			salary_max: toYearly(salary.maxValue ?? salary.value, unit),
			notes: 'Automatisch übernommen (JSON-LD).',
		};
	}

	return null;
}

function toPlainText(html) {
	return html
		.replace(/<script[\s\S]*?<\/script>/gi, ' ')
		.replace(/<style[\s\S]*?<\/style>/gi, ' ')
		.replace(/<[^>]+>/g, ' ')
		.replace(/&nbsp;/g, ' ')
		.replace(/&amp;/g, '&')
		.replace(/\s+/g, ' ')
		.trim()
		.slice(0, 12000);
}

const results = [];

for (const item of $input.all()) {
	let html = '';
	let load_error = null;

	try {
		const response = await this.helpers.httpRequest({
			method: 'GET',
			url: item.json.url,
			headers: { 'User-Agent': 'Mozilla/5.0 (JobTrail)' },
			timeout: 15000,
			json: false,
			returnFullResponse: true,
			ignoreHttpStatusErrors: true,
		});

		if (response.statusCode >= 400) {
			load_error = response.statusCode;
		} else {
			html = response.body;
		}
	} catch (error) {
		load_error = 'unreachable';
	}

	const job = readJobPosting(String(html));
	const text = toPlainText(String(html));

	results.push({
		json: {
			chat_id: item.json.chat_id,
			message_id: item.json.message_id,
			url: item.json.url,
			job: job,
			has_json_ld: job != null && job.company != null && job.position != null,
			text: text,
			readable: text.length >= 300,
			load_error: load_error,
		},
	});
}

return results;

const source = $('Anzeige laden & JSON-LD lesen').item.json;
const output = $json.output ?? {};

return {
	json: {
		chat_id: source.chat_id,
		message_id: source.message_id,
		url: source.url,
		job: {
			company: output.company ?? null,
			position: output.position ?? null,
			location: output.location ?? null,
			remote: output.remote == true,
			salary_min: output.salary_min ?? null,
			salary_max: output.salary_max ?? null,
			notes: (output.summary ?? '') + ' (Automatisch mit KI ausgelesen.)',
		},
	},
};

const source = $('Anzeige laden & JSON-LD lesen').item.json;
const status_code = $json.statusCode;
const data = $json.body?.data;
const errors = $json.body?.errors ?? {};
let text = '';

if (source.load_error == 'unreachable') {
	text = '❌ Die Seite ist nicht erreichbar. Stimmt der Link?\n' + source.url;
} else if (source.load_error == 403 || source.load_error == 429) {
	text = '⚠️ Die Seite blockiert automatische Abrufe. Bitte manuell anlegen:\n' + source.url;
} else if (source.load_error == 404) {
	text = '❌ Die Seite gibt es nicht (404). Ist die Anzeige schon offline?\n' + source.url;
} else if (source.load_error != null) {
	text = '❌ Die Seite konnte nicht geladen werden (Status ' + source.load_error + ').\n' + source.url;
} else if (source.readable == false && source.has_json_ld == false) {
	text = '⚠️ Die Seite lädt ihren Inhalt per JavaScript. Bitte manuell anlegen:\n' + source.url;
} else if (status_code == 201) {
	text = '✅ Gespeichert: ' + data.company + ' – ' + data.position;
} else if (status_code == 200) {
	text = 'ℹ️ Schon vorhanden: ' + data.company + ' – ' + data.position + ' (' + data.status_label + ')';
} else if (status_code == 422 && errors.position != null && errors.company == null) {
	text = '⚠️ Das sieht nach einer Übersichtsseite aus: Firma erkannt, aber keine einzelne Stelle. Bitte den Link zu einer konkreten Stellenanzeige schicken.\n' + source.url;
} else if (status_code == 422) {
	text = '⚠️ Firma oder Stelle konnte nicht ausgelesen werden. Bitte manuell anlegen:\n' + source.url;
} else {
	text = '❌ Fehler beim Speichern (Status ' + (status_code ?? 'unbekannt') + '). Läuft JobTrail?';
}

if (data != null && (status_code == 200 || status_code == 201)) {
	const details = [];

	if (data.salary_min != null) {
		details.push(Math.round(data.salary_min / 1000) + '–' + Math.round((data.salary_max ?? data.salary_min) / 1000) + 'k €');
	}

	if (data.remote == true) {
		details.push('Remote');
	}

	if (data.location != null) {
		details.push(data.location);
	}

	if (details.length > 0) {
		text = text + '\n' + details.join(' · ');
	}

	text = text + '\n' + data.edit_url;
}

return {
	json: {
		chat_id: source.chat_id,
		message_id: source.message_id,
		text: text,
	},
};
